import type { EngineInterface, Register } from 'claude-code'

const FETCH = String.raw`(?:curl|wget|iwr|irm|invoke-webrequest|invoke-restmethod)`
const RUN = String.raw`(?:sh|bash|zsh|dash|ksh|fish|python3?|perl|ruby|node|php|iex|invoke-expression|pwsh|powershell)(?:\.exe)?`

const FETCH_RE = new RegExp(String.raw`\b${FETCH}\b`, 'i')
// A pipeline stage that starts an interpreter, optionally behind sudo/env/command/xargs.
const STAGE_RE = new RegExp(
  String.raw`^[\s({&]*(?:(?:sudo|env|command|exec|xargs)\s+(?:-\S+\s+)*)*(${RUN})\b(.*)$`,
  'is',
)
// Shells and PowerShell execute whatever they read — never a data-only consumer.
const SHELL_RE = /^(?:sh|bash|zsh|dash|ksh|fish|iex|invoke-expression|pwsh|powershell)(?:\.exe)?$/i
// Inline-code flags: python -c, node -e/-p, perl/ruby -e/-ne/-pe, php -r. With one of these,
// stdin is data for the inline program, not code — unless that program executes it.
const INLINE_FLAG_RE = /^\s+-[a-z]*[cepr]\s/i
// Anything that could turn stdin back into code. Heuristic, so it errs towards blocking.
const EXECUTES_RE =
  /\b(?:exec|eval|compile|system|popen|spawn|execSync|spawnSync|instance_eval|class_eval|__import__|importlib|subprocess|child_process|pickle|marshal|dill|vm|Function|qx)\b|`/i

function isDataConsumer(interpreter: string, args: string, command: string) {
  if (SHELL_RE.test(interpreter)) return false
  if (/^python3?$/i.test(interpreter) && /^\s+-m\s+json\.tool\b/.test(args)) return true
  return INLINE_FLAG_RE.test(args) && !EXECUTES_RE.test(command)
}

// Downloaded output piped into an interpreter, through any number of pipeline stages
// (so `curl … | tee f | sh` is caught too).
export function pipesIntoInterpreter(command: string) {
  const stages = command.replace(/\|\|/g, '\n').split('|')
  const first = stages.findIndex(s => FETCH_RE.test(s))
  if (first === -1) return false
  return stages.slice(first + 1).some(stage => {
    const m = STAGE_RE.exec(stage)
    return m !== null && !isDataConsumer(m[1], m[2], command)
  })
}

const OUTPUT_RE = new RegExp(
  String.raw`\b${FETCH}\b[^;&|\n]*?(?:\s(?:-[A-Za-z]*[oO]|--output(?:-document)?|-OutFile)(?:\s+|=)|\s*>\s*)["']?([^\s"';&|<>)]+)`,
  'gi',
)
const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

// Downloaded to a file, then that same file is run in the same command:
// `curl -o i.sh URL && bash i.sh`, `… ; chmod +x i.sh; ./i.sh`, `… && . ./i.sh`.
export function downloadsThenRuns(command: string) {
  for (const m of command.matchAll(OUTPUT_RE)) {
    const file = m[1].replace(/^\.[\/\\]/, '')
    if (file === '-' || /^https?:/i.test(file)) continue
    const rest = command.slice((m.index ?? 0) + m[0].length)
    const f = escapeRe(file)
    const end = String.raw`(?=$|[\s"';&|)])`
    const ways = [
      // bash i.sh, python3 -u i.py, source i.sh
      String.raw`\b(?:${RUN}|source)\s+(?:-\S+\s+)*["']?(?:\.[\/\\])?${f}${end}`,
      // . ./i.sh (dot-source)
      String.raw`(?:^|[\s;&|(])\.\s+["']?(?:\.[\/\\])?${f}${end}`,
      // ./i.sh or .\i.ps1 in command position
      String.raw`(?:^|[;&|(])\s*\.[\/\\]${f}${end}`,
      // /tmp/i.sh in command position, when the download target was a path
      ...(file.includes('/') || file.includes('\\') ? [String.raw`(?:^|[;&|(])\s*["']?${f}${end}`] : []),
    ]
    if (ways.some(w => new RegExp(w, 'i').test(rest))) return true
  }
  return false
}

// Each rule: why it is dangerous, and a check that recognises it.
const RULES: ReadonlyArray<readonly [string, (command: string) => boolean]> = [
  ['تنزيل وتشغيل مباشر (download | shell)', pipesIntoInterpreter],
  ['تنزيل ملف ثم تشغيله في الأمر نفسه', downloadsThenRuns],
  ['تشغيل ناتج تنزيل عبر $( ) أو <( ) أو >( )', c => new RegExp(String.raw`(?:\$\(|<\(|\x60)\s*${FETCH}\b|\b${FETCH}\b[^;&\n]*>\(\s*${RUN}\b`, 'i').test(c)],
  ['PowerShell: iex على محتوى من الإنترنت', c => new RegExp(String.raw`\b(?:iex|invoke-expression)\b[\s(]*(?:\(?\s*new-object\s+(?:system\.)?net\.webclient\)?\s*\.\s*download(?:string|data)|${FETCH}\b)`, 'i').test(c)],
  ['PowerShell بأمر مشفّر (-EncodedCommand)', c => /\b(?:powershell|pwsh)(?:\.exe)?\b.*\s-(?:e|ec|enc|encodedcommand)\s+[A-Za-z0-9+/=]{16,}/i.test(c)],
  ['أداة نظام تُستغل للتنزيل (certutil/bitsadmin/mshta/regsvr32)', c => /\b(?:certutil(?:\.exe)?\b.*-urlcache|bitsadmin(?:\.exe)?\s+\/transfer|mshta(?:\.exe)?\s+["']?(?:https?|javascript|vbscript):|regsvr32(?:\.exe)?\b.*\/i:\s*https?:)/i.test(c)],
  ['Python ينفّذ كوداً منزّلاً', c => /\bexec\s*\(.*\b(?:urlopen|requests\.get|urllib)/i.test(c)],
]

let blocked = 0

export function verdict(command: string): string | undefined {
  for (const [why, matches] of RULES) if (matches(command)) return why
  return undefined
}

function deny($: EngineInterface, why: string) {
  blocked += 1
  $.ui.toast(`🧱 script-gate: ${why}`)
  $.ui.status(`🧱 سكربتات محجوبة: ${blocked}`)
  return {
    deny:
      `script-gate: blocked — ${why}. ` +
      'Running code straight from the internet is not allowed here. ' +
      'Download it to a file instead, show the user the full URL and the script contents, ' +
      'and run it only after the user explicitly approves.',
  }
}

export const register: Register = on => {
  on('tool.call', { tool: 'Bash' }, ($, e, next) => {
    const why = verdict(e.command)
    return why === undefined ? next(e) : deny($, why)
  })
}

